import subprocess


def read_title(revision: str) -> str:
    result = subprocess.run(
        f"git show -s --format=%s {revision}",
        shell=True,
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout.strip()

after_files.tests/test_git_title.py:
from subprocess import CompletedProcess

from src import git_title


def test_read_title(monkeypatch) -> None:
    observed: list[object] = []

    def fake_run(command, **kwargs):
        observed.append(command)
        return CompletedProcess(command, 0, stdout="Release title\n", stderr="")

    monkeypatch.setattr(git_title.subprocess, "run", fake_run)
    assert git_title.read_title("HEAD") == "Release title"
    assert observed == ["git show -s --format=%s HEAD"]

